const stateApi = window.prototypeState;
const app = document.querySelector("#app");
const breadcrumb = document.querySelector("#breadcrumb");

const state = () => stateApi.getState();
const find = (collection, id) => state()[collection].find((item) => item.id === id);
const icon = (name) => `<i data-lucide="${name}"></i>`;
const link = (href, text, className = "inline-link") => `<a class="${className}" href="#/${href}">${text}</a>`;
const problemLink = (id) => link(`problems/${id}`, id);
const operationLink = (id) => link(`operations/${id}`, id);
const initials = (name = "Unassigned") => name.split(" ").map((part) => part[0]).join("").slice(0, 2);
const tag = (value) => `<span class="status ${String(value || "").toLowerCase().replaceAll(" ", "-")}"><i></i>${value || "Not started"}</span>`;
const empty = (title, copy, iconName = "layers-2") => `<section class="empty-state">${icon(iconName)}<h2>${title}</h2><p>${copy}</p></section>`;

function pageHeader(eyebrow, title, description, actions = "") {
  return `<section class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="page-description">${description}</p></div><div class="page-actions">${actions}</div></section>`;
}
function setBreadcrumb(parts) { breadcrumb.innerHTML = parts.map((part, index) => `${index ? icon("chevron-right") : ""}<span>${part}</span>`).join(""); }
function detailMetric(label, value, hint) { return `<div class="detail-metric"><small>${label}</small><strong>${value}</strong>${hint ? `<span>${hint}</span>` : ""}</div>`; }
function operationProgress(operation) { const actions = state().actions.filter((action) => action.operationId === operation.id); const complete = actions.filter((action) => action.status === "Completed").length; return { actions, complete, percent: actions.length ? Math.round((complete / actions.length) * 100) : 0 }; }

function actionControl(action) {
  if (action.status === "Completed") return `<span class="action-complete-label">${icon("check-circle-2")}Completed</span>`;
  if (action.name === "Run regional Probe") return `<button class="secondary-button action-button" type="button" data-action="run-probe" data-operation-id="${action.operationId}" data-action-id="${action.id}">${icon("radar")}Run Probe</button>`;
  return `<button class="secondary-button action-button" type="button" data-action="complete-action" data-action-id="${action.id}">${icon("check")}Mark as Completed</button>`;
}

function recommendation(problem, operation) {
  if (!operation) return { title: "Investigate approval download instability in China", why: "The Probe has detected abnormal customer behavior, but no Backend Incident exists. Operation should establish an accountable response before waiting for a report.", owner: "Operation Manager", expected: "Create an Operation with a measurable failure-rate and availability target.", evidence: ["Probe failure 12.8%", "Availability 96.1%", "Incident count 0"], action: "create-operation", actionLabel: "Create Operation" };
  if (operation.status === "Completed" || state().outcomes.some((outcome) => outcome.operationId === operation.id)) return { title: "Outcome achieved", why: "Verification passed and the target was met. Keep the same independent evidence observable for recurrence.", owner: operation.owner, expected: "Maintain the improvement and monitor for a new Signal.", evidence: [`Actual ${operation.verification?.actual || "0.4%"}`, `Availability ${operation.verification?.availability || "99.8%"}`, "Verification PASSED"], action: "history", actionLabel: "View Closed-loop History" };
  if (!find("probeResults", "PR-001")) return { title: "Run regional Probe in China", why: "The Operation needs an independent baseline after investigation, before a backend fix can be evaluated.", owner: "Operation Engineer · Probe Ops", expected: "Capture a current Probe Result and link it as Problem Evidence.", evidence: ["Probe failure 12.8%", "Availability 96.1%", "Incident count 0"], action: "run-probe", actionLabel: "Run Probe" };
  if (!find("actions", "ACT-002") || find("actions", "ACT-002").status !== "Completed") return { title: "Deploy backend fix associated with REL-CN-002", why: "The diagnostic Probe confirms the failure is still present. The next accountable action is to deploy the mitigation and attach Action Evidence.", owner: "Backend MIB3", expected: "Remove the HTTP 500 regression and move the Operation into verification.", evidence: ["PR-001 = 12.8%", "EVD-001 Problem Evidence", "Target < 1%"], action: "complete-action", actionId: "ACT-002", actionLabel: "Mark Fix Completed" };
  if (!operation.verification) return { title: "Run verification Probe in China", why: "The backend fix is complete, but an Operation is not successful until an independent Probe proves the outcome.", owner: "Probe Ops · Operation Manager", expected: "Measure failure below 1% and availability above 99.7%.", evidence: ["REL-CN-002 deployed", "HTTP 500 regression addressed", "Verification is required"], action: "run-verification", actionLabel: "Run Verification Probe" };
  if (operation.verification.status === "Pending Review") return { title: "Record verification against the target", why: "A verification Probe Result and Outcome Evidence are ready for an explicit pass/fail decision.", owner: operation.owner, expected: "Record PASSED or FAILED; only PASSED can complete the Operation.", evidence: [`Actual ${operation.verification.actual}`, `Availability ${operation.verification.availability}`, "Expected < 1%"], action: "record-verification", actionLabel: "Record Verification" };
  if (operation.verification.status === "Failed") return { title: "Create a new corrective Action", why: "Verification failed, so the Operation must remain Verifying and receive new work instead of being closed.", owner: operation.owner, expected: "Address the remaining failure and run another verification Probe.", evidence: [`Actual ${operation.verification.actual}`, "Verification FAILED", "Operation remains Verifying"], action: "create-action", actionLabel: "Create New Action" };
  return { title: "Outcome achieved", why: "Verification passed and the target was met. Review the closed-loop record for the reusable outcome.", owner: operation.owner, expected: "Problem is resolved and the Operation is completed with evidence.", evidence: [`Actual ${operation.verification.actual}`, `Availability ${operation.verification.availability}`, "Verification PASSED"], action: "history", actionLabel: "View Closed-loop History" };
}
function recommendationButton(item, problemId, operationId) { if (item.action === "history") return link("history", `${icon("history")}${item.actionLabel}`, "secondary-button"); const attrs = `data-action="${item.action}" data-problem-id="${problemId}"${item.actionId ? ` data-action-id="${item.actionId}"` : ""}${operationId ? ` data-operation-id="${operationId}"` : ""}`; return `<button class="primary-button" type="button" ${attrs}>${icon(item.action.includes("probe") ? "radar" : item.action.includes("operation") ? "plus" : item.action.includes("verification") ? "badge-check" : "wrench")}${item.actionLabel}</button>`; }

function executiveKpi(label, href, value, description, tone = "") { return `<a class="executive-kpi ${tone}" href="#/${href}"><span>${label}${icon("arrow-up-right")}</span><strong>${value}</strong><small>${description}</small></a>`; }
function renderOverview() {
  const health = stateApi.getOperationHealth();
  const summary = stateApi.getExecutiveSummary();
  const metrics = stateApi.getClosedLoopMetrics();
  const impact = stateApi.getBusinessImpact();
  const services = stateApi.getChinaServiceHealth();
  const completed = stateApi.getCompletedOperations();
  const risks = stateApi.getRiskServices();
  const leadOutcome = completed[0]?.outcome;
  const leadOperation = completed[0]?.operation;
  const leadProblem = completed[0]?.problem;
  const outcomeHref = leadOutcome ? `outcomes/${leadOutcome.id}` : "history";
  const flowSteps = [
    ["Signals detected", metrics.signalsDetected, "Source facts", ""],
    ["Problems created", metrics.problemsCreated, "Correlated", metrics.conversion.problems],
    ["Operations started", metrics.operationsStarted, "Accountable action", metrics.conversion.operations],
    ["Operations completed", metrics.operationsCompleted, "Verified work", metrics.conversion.completed],
    ["Verified Outcomes", metrics.outcomesVerified, "Business result", metrics.conversion.outcomes]
  ];
  return `${pageHeader("OVERVIEW · CHINA", "China Operation Overview", "Operational health, resolved risks, and verified improvements across China services.", `<button class="secondary-button" type="button" data-action="reset">${icon("rotate-ccw")}Reset demo state</button>`)}
    <section class="overview-toolbar"><div><span class="toolbar-label">Region</span><strong>${icon("map-pin")}China</strong></div><div class="range-control" aria-label="Time range"><button type="button">Today</button><button class="is-active" type="button">7 Days</button><button type="button">30 Days</button></div></section>
    <section class="overview-health ${health.tone}"><div class="health-mark">${icon(health.tone === "healthy" ? "shield-check" : health.tone === "warning" ? "triangle-alert" : "octagon-alert")}</div><div><p class="eyebrow">OPERATION HEALTH</p><h2>${health.label}</h2><p>${health.reason}. Health combines current service risk, active Operations, and verification evidence.</p></div><a href="#/command-center">Open attention queue ${icon("arrow-right")}</a></section>
    <section class="overview-section"><div class="overview-section-head"><div><p class="eyebrow">EXECUTIVE SUMMARY</p><h2>Operation results at a glance</h2></div><span>Selected period · China</span></div><div class="executive-kpi-grid">${executiveKpi("TOTAL PROBLEMS", "problems", summary.totalProblems, "Problems detected in selected period")}${executiveKpi("RESOLVED PROBLEMS", "problems?status=Resolved", summary.resolvedProblems, "Problems closed after verification", "positive")}${executiveKpi("VERIFIED IMPROVEMENT", outcomeHref, summary.verifiedImprovement, "Average availability improvement after operations", "positive")}${executiveKpi("RISK REDUCTION", "history", summary.riskReduction, "Operational risk reduction", "risk-reduction")}</div></section>
    <section class="surface service-health executive-surface"><div class="surface-head"><div><p class="eyebrow">SERVICE HEALTH · CHINA</p><h2>Where is operational health at risk?</h2></div><span class="surface-note">Availability + Probe + Problems</span></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Availability</th><th>Failure rate</th><th>Probe success</th><th>Open Problems</th><th>Status</th></tr></thead><tbody>${services.map((service) => { const risk = risks.find((item) => item.service === service.service); return `<tr><td>${risk ? `<a class="entity-link" href="#/problems/${risk.problemId}"><strong>${service.service}</strong><small>China production</small></a>` : `<strong>${service.service}</strong><small>China production</small>`}</td><td>${service.availability}</td><td>${service.failureRate}</td><td>${service.probeSuccess}</td><td>${service.openProblems}</td><td>${tag(service.status)}</td></tr>`; }).join("")}</tbody></table></div></section>
    <section class="overview-section"><div class="overview-section-head"><div><p class="eyebrow">OUTCOME IMPACT</p><h2>Business Impact After Operations</h2></div><a href="#/${outcomeHref}">View verified Outcome ${icon("arrow-right")}</a></div><div class="impact-kpi-grid"><a href="#/${outcomeHref}" class="impact-kpi"><span class="impact-icon">${icon("users")}</span><div><small>USERS RECOVERED</small><strong>${impact.usersRecovered.toLocaleString()}</strong><p>Users recovered after verified fixes</p></div></a><a href="#/${outcomeHref}" class="impact-kpi"><span class="impact-icon">${icon("clock-3")}</span><div><small>DOWNTIME REDUCED</small><strong>${impact.downtimeReduced}</strong><p>Production downtime prevented</p></div></a><a href="#/${outcomeHref}" class="impact-kpi"><span class="impact-icon">${icon("shield-check")}</span><div><small>CUSTOMER RISK</small><strong>${impact.customerRiskBefore} <i>${icon("arrow-right")}</i> ${impact.customerRiskAfter}</strong><p>Risk after evidence-backed recovery</p></div></a></div></section>
    <section class="surface completed-operations"><div class="surface-head"><div><p class="eyebrow">COMPLETED OPERATIONS</p><h2>What did our actions change?</h2></div><a href="#/operations?status=Completed">All completed Operations ${icon("arrow-right")}</a></div>${completed.map(({ operation, problem, outcome, actions }) => `<article class="completed-operation-row"><div class="completed-operation-main"><a class="outcome-id" href="#/operations/${operation.id}">${operation.id}</a><a href="#/problems/${problem.id}"><strong>${problem.title}</strong></a><small>${problem.service} · ${actions.map((action) => action.name).join(", ")}</small></div><div class="operation-comparison"><div><small>BEFORE</small><span>Availability <b>${outcome.beforeMetric.availability}%</b></span><span>Failure <b>${outcome.beforeMetric.failureRate}%</b></span></div>${icon("arrow-right")}<div class="after"><small>AFTER</small><span>Availability <b>${outcome.afterMetric.availability}%</b></span><span>Failure <b>${outcome.afterMetric.failureRate}%</b></span></div></div><div class="operation-result"><strong>${icon("trending-down")} ${outcome.impact.failureReduction}% fewer failures</strong>${tag(outcome.status)}<a href="#/operations/${operation.id}">View Operation ${icon("arrow-right")}</a></div></article>`).join("")}</section>
    <section class="overview-grid executive-analysis-grid"><div class="surface closed-loop"><div class="surface-head"><div><p class="eyebrow">CLOSED-LOOP PERFORMANCE</p><h2>Operational efficiency</h2></div><span class="surface-note">${metrics.closedLoopRate} end-to-end</span></div><div class="executive-funnel">${flowSteps.map(([label, value, hint, rate], index) => `<div class="funnel-stage"><span>${index + 1}</span><div><strong>${value}</strong><b>${label}</b><small>${hint}</small></div>${rate ? `<em>${rate}</em>` : ""}</div>`).join("")}</div></div><div class="surface risk-services"><div class="surface-head"><div><p class="eyebrow">RISK SERVICE RANKING</p><h2>Services requiring attention</h2></div><a href="#/command-center">Attention queue ${icon("arrow-right")}</a></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Risk</th><th>Availability</th><th>Issue</th><th>Action</th></tr></thead><tbody>${risks.map((item) => `<tr><td><a class="entity-link" href="#/problems/${item.problemId}"><strong>${item.service}</strong><small>${item.region} · ${item.probeFailure} Probe failure</small></a></td><td>${tag(item.risk)}</td><td>${item.availability}</td><td>${item.issue}</td><td>${item.activeOperation ? `<a class="inline-link" href="#/operations/${item.activeOperation}">View Operation</a>` : `<a class="inline-link" href="#/problems/${item.problemId}">View Problem</a>`}</td></tr>`).join("")}</tbody></table></div></div></section>
    <section class="surface trend-overview executive-trend"><div class="surface-head"><div><p class="eyebrow">TREND ANALYSIS · 7 DAYS</p><h2>Operation changed the result</h2></div><span class="trend-legend"><b></b>Failure rate <b></b>Availability <b></b>Closed-loop</span></div><div class="trend-content"><div class="trend-outcome"><div><small>BEFORE OPERATION</small><strong>${leadOutcome?.beforeMetric.failureRate || 12.8}%</strong><span>Failure rate</span></div><span>${icon("arrow-right")}</span><div class="after"><small>AFTER OPERATION</small><strong>${leadOutcome?.afterMetric.failureRate || 0.4}%</strong><span>Verified failure rate</span></div><a href="#/${outcomeHref}">${icon("badge-check")}Verified by Probe</a></div><div class="trend-chart"><div class="trend-y"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div class="trend-plot"><div class="trend-grid-lines"><i></i><i></i><i></i><i></i><i></i></div><svg viewBox="0 0 700 180" role="img" aria-label="Seven day operation trend showing improving availability and falling failure rate"><polyline points="0,62 115,78 230,91 345,119 460,139 575,154 700,164" fill="none" stroke="#2f6fed" stroke-width="3"/><polyline points="0,42 115,37 230,31 345,25 460,20 575,16 700,13" fill="none" stroke="#12b76a" stroke-width="3"/><polyline points="0,113 115,103 230,91 345,78 460,63 575,50 700,39" fill="none" stroke="#f79009" stroke-width="3"/></svg><div class="trend-marker"><span>OP-101 completed</span></div><div class="trend-x"><span>Aug 22</span><span>Aug 24</span><span>Aug 26</span><span>Aug 28</span></div></div></div></div></section>
    <section class="surface operational-insights"><div class="insight-icon">${icon("lightbulb")}</div><div><p class="eyebrow">OPERATIONAL INSIGHTS</p><h2>${leadProblem?.title || "Approval Download instability"} was resolved</h2><p><strong>OP-101</strong> reduced failure rate from <strong>${leadOutcome?.beforeMetric.failureRate || 12.8}%</strong> to <strong>${leadOutcome?.afterMetric.failureRate || 0.4}%</strong>, restored availability to <strong>${leadOutcome?.afterMetric.availability || 99.8}%</strong>, and protected <strong>${(leadOutcome?.impact.usersRecovered || 12450).toLocaleString()} users</strong>. A new recurrence signal remains visible in the attention queue.</p></div><div class="insight-actions"><a class="secondary-button" href="#/operations/${leadOperation?.id || "OP-101"}">View Operation</a><a class="primary-button" href="#/${outcomeHref}">View Outcome ${icon("arrow-right")}</a></div></section>`;
}

function renderSignals(query = {}) {
  const signals = state().signals.filter((signal) => !query.status || signal.status.toLowerCase().includes(query.status.toLowerCase()));
  const critical = signals.filter((signal) => signal.severity === "Critical").length;
  const needInvestigation = signals.filter((signal) => ["Detected", "Analyzing"].includes(signal.status)).length;
  const correlated = signals.filter((signal) => signal.problemId || signal.status === "Correlated" || signal.status === "Problem Created").length;
  return `${pageHeader("INVESTIGATE · SIGNALS", "China Signal Center", "What abnormal signals are happening in China now? Signal is the unified entry object, not an Incident.", `<button class="primary-button" type="button" data-action="new-signal">${icon("plus")}New Signal</button>`)}<section class="signal-summary"><div>${detailMetric("NEW SIGNALS", signals.filter((signal) => signal.status === "Detected").length, "Detected facts")}</div><div>${detailMetric("CRITICAL SIGNALS", critical, "Immediate review")}</div><div>${detailMetric("NEED INVESTIGATION", needInvestigation, "Detected or analyzing")}</div><div>${detailMetric("CORRELATED SIGNALS", correlated, "Linked to a Problem")}</div></section><section class="surface"><div class="table-wrap"><table class="signals-table"><thead><tr><th>Signal</th><th>Source</th><th>Service</th><th>Region</th><th>Type</th><th>Severity</th><th>Metric</th><th>Status</th><th>Detected</th><th>Action</th></tr></thead><tbody>${signals.map((signal) => `<tr><td><a class="entity-link" href="#/signals/${signal.id}"><strong>${signal.id}</strong><small>${signal.description || "Observed abnormal condition"}</small></a></td><td>${signal.source}</td><td>${signal.service}</td><td>${signal.region}</td><td>${signal.type}</td><td>${tag(signal.severity)}</td><td>${signal.metric?.name || signal.metric} ${signal.metric?.value != null ? `${signal.metric.value}${signal.metric.unit || ""}` : signal.actual || ""}</td><td>${tag(signal.status)}</td><td>${signal.timestamp}</td><td><a class="secondary-button compact-button" href="#/signals/${signal.id}">${icon("scan-search")}Investigate</a></td></tr>`).join("")}</tbody></table></div></section>`;
}

function renderSignalDetail(id) {
  const signal = stateApi.getSignalById(id);
  if (!signal) return empty("Signal not found", "The requested Signal does not exist.", "circle-off");
  const related = state().signals.filter((item) => item.id !== signal.id && item.service === signal.service && item.region === signal.region);
  const correlation = stateApi.correlateSignals([signal.id, ...related.map((item) => item.id)]);
  const problem = signal.problemId && find("problems", signal.problemId);
  return `<a class="back-link" href="#/signals">${icon("arrow-left")}All Signals</a><section class="detail-hero signal-hero"><div><div class="title-meta"><span>${signal.id}</span>${tag(signal.status)}${tag(signal.severity)}</div><h1>${signal.description || `${signal.type} detected`}</h1><p>${signal.service} · ${signal.region} · ${signal.environment} · ${signal.timestamp}</p><div class="detail-context"><span>${icon("radio-tower")} ${signal.source}</span><span>${icon("boxes")} ${signal.service}</span><span>${icon("map-pin")} ${signal.region}</span></div></div><div class="hero-actions"><div>${tag(signal.severity)}<small>severity</small></div></div></section><section class="signal-detail-grid"><div class="left-detail-stack"><section class="surface"><div class="surface-head"><div><p class="eyebrow">SIGNAL FACTS</p><h2>Observed condition</h2></div></div><dl class="signal-facts"><dt>Source</dt><dd>${signal.source}</dd><dt>Type</dt><dd>${signal.type}</dd><dt>Environment</dt><dd>${signal.environment}</dd><dt>Detected</dt><dd>${signal.timestamp}</dd><dt>Related object</dt><dd>${signal.relatedObjects.join(", ") || "-"}</dd></dl></section><section class="surface signal-metric-card"><div class="surface-head"><div><p class="eyebrow">METRIC</p><h2>${signal.metric?.name || "Observed metric"}</h2></div></div><div class="metric-comparison"><div><small>ACTUAL</small><strong>${signal.metric?.value ?? "-"}${signal.metric?.unit || ""}</strong></div><div><small>EXPECTED</small><strong>${signal.metric?.threshold != null ? `${signal.metric.threshold}${signal.metric.unit || ""}` : "-"}</strong></div><div><small>DEVIATION</small><strong>${signal.metric?.value != null && signal.metric?.threshold != null ? `${signal.metric.value >= signal.metric.threshold ? "+" : ""}${(signal.metric.value - signal.metric.threshold).toFixed(1)}${signal.metric.unit || ""}` : "-"}</strong></div></div></section><section class="surface"><div class="surface-head"><div><p class="eyebrow">RELATED SIGNALS</p><h2>Independent context</h2></div></div><div class="related-signal-list">${related.length ? related.map((item) => `<a href="#/signals/${item.id}"><span class="source-icon ${item.source.toLowerCase()}">${icon(item.source === "Probe" ? "radar" : item.source === "Availability" ? "activity" : "radio-tower")}</span><div><strong>${item.id} · ${item.type}</strong><small>${item.source} · ${item.metric?.value ?? "-"}${item.metric?.unit || ""} · ${item.timestamp}</small></div>${tag(item.status)}</a>`).join("") : `<div class="quiet-state">No related Signal has been correlated yet.</div>`}</div></section></div><aside class="surface signal-correlation-card"><div class="surface-head"><div><p class="eyebrow">CORRELATION RESULT</p><h2>${problem ? "Problem created" : "Possible Problem detected"}</h2></div></div><div class="confidence-score"><strong>${correlation.confidence}%</strong><span>confidence</span></div><p class="correlation-copy">${correlation.possibleProblem ? "The evidence pattern is strong enough for an accountable Operation response." : "More independent context is needed before creating a Problem."}</p><div class="correlation-list">${correlation.reasons.map((reason) => `<span>${icon("check-circle-2")}${reason}</span>`).join("")}</div>${problem ? `<a class="primary-button full-button" href="#/problems/${problem.id}">${icon("git-fork")}Open ${problem.id}</a>` : `<button class="primary-button full-button" type="button" data-action="create-problem-from-signal" data-signal-id="${signal.id}">${icon("git-fork")}Create Problem</button>`}</aside></section>`;
}

function renderCommandCenter() {
  const current = state();
  const unreported = current.problems.filter((problem) => problem.unreported && !["Resolved", "Closed"].includes(problem.status));
  const active = current.operations.filter((operation) => !["Completed", "Closed", "Cancelled"].includes(operation.status));
  const verification = active.filter((operation) => operation.status === "Verifying" || operation.verificationStatus === "Pending Review");
  const critical = current.problems.filter((problem) => problem.risk === "Critical" && !["Resolved", "Closed"].includes(problem.status)).length;
  const attentionProblems = current.problems.filter((problem) => !["Resolved", "Closed"].includes(problem.status));
  return `${pageHeader("LIVE OPERATIONS", "What needs your attention today?", "Prioritized decisions across business impact, risk, unreported signals, active Operations, and verification outcomes.", `<button class="secondary-button" type="button" data-action="reset">${icon("rotate-ccw")}Reset demo state</button>`)}<section class="attention-grid"><a class="attention-card critical-card" href="#/problems?severity=Critical"><span>Critical problems</span><strong>${critical}</strong><p>Immediate business risk</p><small>${critical ? "2,000 users affected" : "No immediate business risk"} ${icon("arrow-up-right")}</small></a><a class="attention-card warning-card" href="#/operations"><span>Verification / outcome</span><strong>${verification.length}</strong><p>Evidence needs an explicit decision</p><small>Review before closing ${icon("arrow-up-right")}</small></a><a class="attention-card watch-card" href="#/operations"><span>Active operations</span><strong>${active.length}</strong><p>Accountable response plans</p><small>Open execution board ${icon("arrow-up-right")}</small></a></section>${unreported.map((problem) => `<section class="surface unreported-panel"><div class="unreported-lead"><div class="unreported-icon">${icon("scan-search")}</div><div><p class="eyebrow">UNREPORTED PROBLEM · DETECTED BY PROBE</p><h2>${problem.title}</h2><p>${problem.service} · ${problem.region} · Probe detected abnormality; no Backend Incident exists.</p></div></div><div class="unreported-stats"><div><small>PROBE FAILURE</small><strong>12.8%</strong></div><div><small>AVAILABILITY</small><strong>96.1%</strong></div><div><small>INCIDENTS</small><strong>0</strong></div></div><div class="unreported-actions"><button class="secondary-button" type="button" data-action="investigate" data-problem-id="${problem.id}">Investigate</button><button class="secondary-button" type="button" data-action="adopt-problem" data-problem-id="${problem.id}">Create Problem</button><button class="primary-button" type="button" data-action="create-operation" data-problem-id="${problem.id}">Create Operation</button></div></section>`).join("")}<section class="content-grid command-grid"><div class="surface problem-overview"><div class="surface-head"><div><p class="eyebrow">PRIORITY QUEUE</p><h2>Problems by impact</h2></div><a href="#/problems">All Problems ${icon("arrow-right")}</a></div><div class="table-wrap"><table><thead><tr><th>Problem</th><th>Business impact</th><th>Risk</th><th>Probe</th><th>Operation</th></tr></thead><tbody>${attentionProblems.map((problem) => { const operation = problem.operationIds.map((id) => find("operations", id)).find(Boolean); return `<tr><td><a class="entity-link" href="#/problems/${problem.id}"><strong>${problem.title}</strong><small>${problem.id} · ${problem.service} · ${problem.region}</small></a></td><td>${problem.impact}</td><td>${tag(problem.risk)}</td><td>${problem.unreported ? tag("Unreported") : tag("Connected")}</td><td>${operation ? `${operationLink(operation.id)}<small class="under-text">${tag(operation.status)}</small>` : `<span class="under-text">No Operation</span>`}</td></tr>`; }).join("")}</tbody></table></div></div><div class="surface execution-feed"><div class="surface-head"><div><p class="eyebrow">ACT → VERIFY → OUTCOME</p><h2>Active Operations</h2></div><a href="#/operations">Execution board ${icon("arrow-right")}</a></div><div class="feed-list">${active.length ? active.map((operation) => { const progress = operationProgress(operation); const problem = find("problems", operation.problemId); return `<a href="#/operations/${operation.id}" class="operation-feed-row"><span class="operation-icon">${icon("crosshair")}</span><div><strong>${operation.title}</strong><p>${operation.id} · ${problem.title}</p><div class="progress"><span style="width:${progress.percent}%"></span></div><small>${progress.complete}/${progress.actions.length} actions complete · ${operation.verificationStatus}</small></div>${tag(operation.status)}</a>`; }).join("") : empty("No active Operations", "Create an Operation from a detected Problem.", "crosshair")}</div></div></section><section class="surface command-verification"><div class="surface-head"><div><p class="eyebrow">VERIFY / OUTCOME</p><h2>Evidence-backed decisions</h2></div><a href="#/history">Closed-loop History ${icon("arrow-right")}</a></div>${verification.length ? verification.map((operation) => `<a class="verification-row" href="#/operations/${operation.id}"><span class="source-icon probe">${icon("badge-check")}</span><div><strong>${operation.title}</strong><p>${operation.id} · ${operation.verification ? `Actual ${operation.verification.actual} · Availability ${operation.verification.availability}` : "Awaiting verification Probe"}</p></div>${tag(operation.verificationStatus)}${icon("chevron-right")}</a>`).join("") : `<div class="quiet-state">No Operation is awaiting an evidence-backed outcome.</div>`}</section>`;
}

function renderProblems(query = {}) {
  const problems = state().problems.filter((problem) => (!query.status || (query.status === "Open" ? !["Resolved", "Closed"].includes(problem.status) : problem.status === query.status)) && (!query.severity || problem.risk === query.severity));
  return `${pageHeader("INVESTIGATE", "Problems", "What problems currently exist? Problems are patterns across signals, impact, evidence, and response.", "")}<section class="filter-bar"><div class="filter-input">${icon("search")}<input aria-label="Search problems" placeholder="Search problems, services, or regions" /></div><span>${problems.length} Problems${query.severity ? ` · ${query.severity}` : query.status ? ` · ${query.status}` : ""}</span></section><section class="surface"><div class="table-wrap"><table class="problems-table"><thead><tr><th>Problem</th><th>Service</th><th>Impact</th><th>Risk</th><th>Signals</th><th>Incidents</th><th>Probe</th><th>Availability</th><th>Operation</th><th>SBT risk</th><th>Status</th></tr></thead><tbody>${problems.map((problem) => { const operation = problem.operationIds.map((id) => find("operations", id)).find(Boolean); const availability = problem.id === "PRB-204" ? operation?.verification?.availability || "96.1%" : "99.2%"; return `<tr><td><a class="entity-link" href="#/problems/${problem.id}"><strong>${problem.title}</strong><small>${problem.id} · ${problem.region}</small></a></td><td>${problem.service}</td><td>${problem.impact}</td><td>${tag(problem.risk)}</td><td>${problem.signalIds.length || (problem.id === "PRB-204" ? 1 : 0)}</td><td>${state().incidents.filter((incident) => incident.problemId === problem.id).length}</td><td>${problem.unreported ? tag("Unreported") : tag("Connected")}</td><td>${availability}</td><td>${operation ? tag(operation.status) : "-"}</td><td>${tag(problem.sbtRisk)}</td><td>${tag(problem.status)}</td></tr>`; }).join("")}</tbody></table></div></section>`;
}

function renderProblemDetail(id) {
  const problem = find("problems", id);
  if (!problem) return empty("Problem not found", "The requested Problem does not exist.", "circle-off");
  const incidents = state().incidents.filter((incident) => incident.problemId === id);
  const evidence = state().evidences.filter((item) => item.problemId === id);
  const results = state().probeResults.filter((result) => result.problemId === id);
  const operations = problem.operationIds.map((operationId) => find("operations", operationId)).filter(Boolean);
  const activeOperations = operations.filter((item) => !["Completed", "Closed", "Cancelled"].includes(item.status));
  const operation = operations[0];
  const latestProbe = results.at(-1)?.actual || "12.8%";
  const latestAvailability = operation?.verification?.availability || "96.1%";
  const next = recommendation(problem, operation);
  const history = state().historyEvents.filter((event) => event.problemId === id);
  return `<a class="back-link" href="#/problems">${icon("arrow-left")}All problems</a><section class="detail-hero"><div><div class="title-meta"><span>${problem.id}</span>${tag(problem.status)}${problem.unreported ? `<span class="unreported-tag">${icon("scan-search")}Unreported</span>` : ""}</div><h1>${problem.title}</h1><p>${problem.description}</p><div class="detail-context"><span>${icon("boxes")} ${problem.service}</span><span>${icon("map-pin")} ${problem.region}</span><span>${icon("tag")} ${problem.category}</span></div></div><div class="hero-actions"><div>${tag(problem.risk)}<small>risk level</small></div><button class="secondary-button" data-action="correlation" type="button">${icon("git-fork")}View correlation</button></div></section>${problem.unreported ? `<section class="alert-strip unreported-alert"><div class="alert-icon">${icon("triangle-alert")}</div><div><strong>Unreported Problem: Probe evidence exists before a Backend Incident</strong><p>Operation can investigate and act without waiting for Incident creation.</p></div><button class="primary-button" type="button" data-action="create-operation" data-problem-id="${problem.id}">Create Operation</button></section>` : ""}<section class="metric-row">${detailMetric("BUSINESS IMPACT", problem.impact, "Current estimate")}${detailMetric("SIGNALS", problem.signalIds.length || 1, "Independent detections")}${detailMetric("INCIDENTS", incidents.length, incidents.length ? "Technical context" : "No report exists")}${detailMetric("PROBE FAILURE", latestProbe, "Latest observed")}${detailMetric("AVAILABILITY", latestAvailability, "Latest service evidence")}</section><section class="recommended-next"><div class="recommendation-icon">${icon("sparkles")}</div><div class="recommendation-copy"><p class="eyebrow">RECOMMENDED NEXT ACTION</p><h2>${next.title}</h2><p>${next.why}</p><div class="recommendation-evidence"><span>Supported by</span>${next.evidence.map((item) => `<b>${icon("check-circle-2")}${item}</b>`).join("")}</div></div><div class="recommendation-decision"><div><small>OWNER</small><strong>${next.owner}</strong></div><div><small>EXPECTED OUTCOME</small><strong>${next.expected}</strong></div><div class="recommendation-buttons">${recommendationButton(next, problem.id, operation?.id)}</div></div></section><section class="detail-grid"><div class="left-detail-stack"><div class="surface"><div class="surface-head"><div><p class="eyebrow">EVIDENCE</p><h2>What we know</h2></div><a href="#/evidence">Evidence library ${icon("arrow-right")}</a></div><div class="evidence-list">${evidence.length ? evidence.map((item) => `<button class="evidence-row evidence-button" type="button" data-evidence-id="${item.id}"><span class="source-icon ${item.source.toLowerCase().replaceAll(" ", "-")}">${icon(item.source === "Probe" ? "radar" : item.source === "Availability" ? "activity" : "siren")}</span><div><strong>${item.metric}</strong><p>${item.category} · ${item.source} · ${item.timestamp}</p></div><div><b>${item.actual}</b><small>expected ${item.expected}</small></div>${tag(item.status)}</button>`).join("") : empty("No Evidence yet", "Run a Probe or connect a source to begin verification.", "shield")}</div></div><div class="surface active-operations-surface"><div class="surface-head"><div><p class="eyebrow">ACTIVE OPERATIONS</p><h2>Response in progress</h2></div><button class="text-button" data-action="create-operation" data-problem-id="${problem.id}" type="button">${icon("plus")}Add Operation</button></div>${activeOperations.length ? activeOperations.map(operationSnapshot).join("") : empty("No active Operation", "Completed response plans remain available in the Operations and History views.", "crosshair")}</div><div class="surface probe-results-surface"><div class="surface-head"><div><p class="eyebrow">PROBE RESULTS</p><h2>Independent observations</h2></div><a href="#/probe">Open Probe ${icon("arrow-right")}</a></div>${results.length ? results.map((result) => `<div class="probe-result-row"><span class="source-icon probe">${icon("radar")}</span><div><strong>${result.id} · ${result.metric}</strong><p>${result.service} · ${result.region} · ${result.timestamp}</p></div><div><b>${result.actual}</b><small>Expected ${result.expected}</small></div>${tag(result.status)}</div>`).join("") : `<div class="quiet-state">No Operation Probe Result yet. The initial signal is represented by the Problem Evidence above.</div>`}</div></div><aside class="surface timeline-surface"><div class="surface-head"><div><p class="eyebrow">CLOSED-LOOP TIMELINE</p><h2>From detection to outcome</h2></div></div><div class="timeline">${history.map(timelineItem).join("")}${history.length < 14 ? timelineItem({ timestamp: "Next", type: "Investigation started", description: "Review the signal and choose the next accountable action.", status: "Next" }) : ""}</div></aside></section>`;
}

function operationSnapshot(operation) { const progress = operationProgress(operation); return `<article class="active-operation-card"><div class="active-operation-head"><div><p class="eyebrow">${operation.id}</p><h3>${operation.title}</h3></div>${tag(operation.status)}</div><p class="operation-objective">${operation.objective}</p><div class="operation-meta"><span>${icon("user-round")} ${operation.owner}</span><span>${icon("calendar-days")} ${operation.targetTime}</span></div><div class="operation-progress"><div class="progress"><span style="width:${progress.percent}%"></span></div><small>${progress.complete}/${progress.actions.length} actions complete</small></div><div class="operation-actions-preview">${progress.actions.length ? progress.actions.map((action) => `<span class="${action.status === "Completed" ? "done" : ""}">${action.status === "Completed" ? icon("check") : icon("circle")} ${action.id} · ${action.name}</span>`).join("") : `<span>${icon("circle")}No Actions created yet</span>`}</div><a class="inline-link operation-link" href="#/operations/${operation.id}">Open Operation ${icon("arrow-right")}</a></article>`; }
function timelineItem(event) { const stateName = event.status === "Completed" ? "complete" : event.status === "Current" ? "current" : "next"; const iconName = event.type.toLowerCase().includes("probe") || event.type.toLowerCase().includes("evidence") ? "radar" : event.type.toLowerCase().includes("operation") || event.type.toLowerCase().includes("action") ? "crosshair" : event.type.toLowerCase().includes("outcome") || event.type.toLowerCase().includes("verification") ? "badge-check" : event.type.toLowerCase().includes("problem") ? "git-fork" : "radio"; return `<div class="timeline-item ${stateName}"><span>${icon(iconName)}</span><div><small>${event.timestamp}</small><strong>${event.type}</strong><p>${event.description}</p></div></div>`; }

function renderOperations(query = {}) { const operations = state().operations.filter((operation) => !query.status || (query.status === "Active" ? !["Completed", "Closed", "Cancelled"].includes(operation.status) : operation.status === query.status)); return `${pageHeader("EXECUTE", "Operations", "What are we doing? Every Operation has an objective, accountable Actions, evidence requirements, and verification status.", `<button class="primary-button" type="button" data-action="create-operation" data-problem-id="PRB-204">${icon("plus")}New Operation</button>`)}<section class="operation-summary"><div>${detailMetric("ACTIVE", state().operations.filter((item) => !["Completed", "Closed"].includes(item.status)).length, "Across Problems")}</div><div>${detailMetric("ACTIONS IN PROGRESS", state().actions.filter((item) => item.status === "In Progress").length, `${state().actions.length} total Actions`)}</div><div>${detailMetric("AWAITING VERIFICATION", state().operations.filter((item) => item.verificationStatus === "Pending Review").length, "Evidence required")}</div></section><section class="surface"><div class="table-wrap"><table><thead><tr><th>Operation</th><th>Problem</th><th>Objective</th><th>Owner</th><th>Progress</th><th>Verification</th><th>Status</th></tr></thead><tbody>${operations.map((operation) => { const progress = operationProgress(operation); return `<tr><td><a class="entity-link" href="#/operations/${operation.id}"><strong>${operation.title}</strong><small>${operation.id} · ${operation.priority}</small></a></td><td>${problemLink(operation.problemId)}</td><td>${operation.objective}</td><td><span class="owner"><b>${initials(operation.owner)}</b>${operation.owner}</span></td><td><div class="progress-wrap"><div class="progress"><span style="width:${progress.percent}%"></span></div><small>${progress.complete}/${progress.actions.length}</small></div></td><td>${tag(operation.verificationStatus)}</td><td>${tag(operation.status)}</td></tr>`; }).join("")}</tbody></table></div></section>`; }

function renderOperationDetail(id) { const operation = find("operations", id); if (!operation) return empty("Operation not found", "The requested Operation does not exist.", "circle-off"); const problem = find("problems", operation.problemId); const progress = operationProgress(operation); const evidence = state().evidences.filter((item) => item.operationId === id); const results = state().probeResults.filter((result) => result.operationId === id); const next = recommendation(problem, operation); return `<a class="back-link" href="#/operations">${icon("arrow-left")}All Operations</a><section class="detail-hero"><div><div class="title-meta"><span>${operation.id}</span>${tag(operation.status)}${problemLink(problem.id)}</div><h1>${operation.title}</h1><p>${operation.objective}</p><div class="detail-context"><span>${icon("user-round")} ${operation.owner}</span><span>${icon("calendar-days")} Target ${operation.targetTime}</span><span>${icon("flag")} ${operation.priority}</span><span>${icon("users")} ${operation.stakeholders.join(", ")}</span></div></div><div class="hero-actions"><div>${tag(operation.verificationStatus)}<small>verification</small></div></div></section><section class="operation-meta-strip"><div><small>TRIGGER</small><strong>${operation.trigger}</strong></div><div><small>CREATED</small><strong>${operation.createdAt}</strong></div><div><small>EXPECTED OUTCOME</small><strong>${operation.expectedOutcome}</strong></div></section><section class="recommended-next compact-recommendation"><div class="recommendation-icon">${icon("route")}</div><div class="recommendation-copy"><p class="eyebrow">NEXT IN CLOSED LOOP</p><h2>${next.title}</h2><p>${next.why}</p></div><div class="recommendation-decision"><div><small>OWNER</small><strong>${next.owner}</strong></div><div class="recommendation-buttons">${recommendationButton(next, problem.id, operation.id)}</div></div></section><section class="detail-grid operation-detail-grid"><div class="left-detail-stack"><div class="surface"><div class="surface-head"><div><p class="eyebrow">ACTION PLAN</p><h2>Execution board <span class="counter-badge">${progress.complete}/${progress.actions.length}</span></h2></div><button class="text-button" type="button" data-action="create-action" data-operation-id="${operation.id}">${icon("plus")}Create Action</button></div><div class="action-list">${progress.actions.length ? progress.actions.map((action) => `<div class="action-row"><span class="action-check ${action.status === "Completed" ? "done" : ""}">${action.status === "Completed" ? icon("check") : ""}</span><div><strong>${action.id} · ${action.name}</strong><p>${action.description}</p><small>${action.owner} · due ${action.dueDate} · Expected: ${action.expectedResult}</small>${action.evidenceIds.length ? `<small class="action-evidence">Evidence: ${action.evidenceIds.join(", ")}</small>` : ""}</div>${tag(action.status)}${actionControl(action)}</div>`).join("") : empty("No Actions yet", "Create ACT-001 to start the Operation.", "list-plus")}</div></div><div class="surface verification-surface"><div class="surface-head"><div><p class="eyebrow">VERIFICATION</p><h2>Did the action work?</h2></div>${operation.verification?.status === "Pending Review" ? `<button class="primary-button" type="button" data-action="record-verification" data-operation-id="${operation.id}">${icon("badge-check")}Record Verification</button>` : ""}</div>${results.length ? `<div class="before-after"><div><small>BEFORE</small><strong>12.8%</strong><p>PR-001 diagnostic Probe</p></div><span>${icon("arrow-right")}</span><div class="after-result"><small>AFTER</small><strong>${operation.verification?.actual || "Awaiting result"}</strong><p>${operation.verification ? `Availability ${operation.verification.availability}` : "Run verification Probe"}</p></div></div><div class="evidence-list compact-evidence">${results.map((result) => `<div class="probe-result-row"><span class="source-icon probe">${icon("radar")}</span><div><strong>${result.id} · ${result.status}</strong><p>${result.metric} · ${result.timestamp}</p></div><div><b>${result.actual}</b><small>Expected ${result.expected}</small></div>${tag(result.status)}</div>`).join("")}</div>` : `<div class="verification-empty">Complete ACT-001 and Deploy backend fix before running the verification Probe.</div>`}${operation.verification?.status === "Failed" ? `<div class="verification-failed"><strong>Verification Failed</strong><p>Actual ${operation.verification.actual} is above the &lt; 1% target. Operation remains Verifying.</p><button class="secondary-button" data-action="create-action" data-operation-id="${operation.id}" type="button">${icon("plus")}Create New Action</button></div>` : ""}</div></div><aside class="surface outcome-surface"><div class="surface-head"><div><p class="eyebrow">OUTCOME</p><h2>Close the loop</h2></div></div><div class="outcome-block"><small>EXPECTED</small><p>${operation.expectedOutcome}</p></div><div class="outcome-block"><small>VERIFICATION</small><p>${operation.verification ? `${operation.verification.status} · ${operation.verification.actual} · Availability ${operation.verification.availability}` : "Not run"}</p></div><div class="outcome-block"><small>CONCLUSION</small><strong>${state().outcomes.find((outcome) => outcome.operationId === id)?.result || "Pending evidence-backed verification"}</strong></div>${operation.verification?.status === "Pending Review" ? `<button class="primary-button full-button" type="button" data-action="record-verification" data-operation-id="${operation.id}">${icon("badge-check")}Record Verification</button>` : ""}<p class="fine-print">Action Completed does not complete an Operation. Only passed verification can produce an Outcome.</p></aside></section>`; }

function renderEvidence() { return `${pageHeader("VERIFY", "Evidence", "What evidence do we have? One library for Problem, Action, and Outcome Evidence from independent sources.", "")}<section class="evidence-legend"><span>${icon("radar")}Probe validates behavior</span><span>${icon("activity")}Availability shows impact</span><span>${icon("siren")}Incident adds context</span><span>${icon("git-commit-horizontal")}CR proves intervention</span></section><section class="surface"><div class="table-wrap"><table><thead><tr><th>Evidence</th><th>Category</th><th>Problem</th><th>Operation</th><th>Action</th><th>Expected</th><th>Actual</th><th>Status</th></tr></thead><tbody>${state().evidences.map((item) => `<tr><td><button class="evidence-entity" type="button" data-evidence-id="${item.id}"><span class="source-icon ${item.source.toLowerCase().replaceAll(" ", "-")}">${icon(item.source === "Probe" ? "radar" : item.source === "Availability" ? "activity" : item.source.includes("CR") ? "git-commit-horizontal" : "siren")}</span><span><strong>${item.metric}</strong><small>${item.id} · ${item.source} · ${item.timestamp}</small></span></button></td><td>${tag(item.category.replace(" Evidence", ""))}</td><td>${problemLink(item.problemId)}</td><td>${item.operationId ? operationLink(item.operationId) : "-"}</td><td>${item.actionId ? link(`operations/${item.operationId}`, item.actionId) : "-"}</td><td>${item.expected}</td><td><strong>${item.actual}</strong></td><td>${tag(item.status)}</td></tr>`).join("")}</tbody></table></div></section>`; }
function renderOutcomeDetail(id) {
  const outcome = state().outcomes.find((item) => item.id === id);
  if (!outcome) return empty("Outcome not found", "The requested Outcome does not exist yet.", "circle-off");
  const operation = find("operations", outcome.operationId);
  const problem = find("problems", outcome.problemId);
  const evidence = outcome.evidenceIds.map((evidenceId) => find("evidences", evidenceId)).filter(Boolean);
  return `<a class="back-link" href="#/overview">${icon("arrow-left")}China Operation Overview</a><section class="detail-hero outcome-detail-hero"><div><div class="title-meta"><span>${outcome.id}</span>${tag(outcome.status)}${operationLink(operation.id)}</div><h1>Verified Outcome</h1><p>${outcome.conclusion}</p><div class="detail-context"><span>${icon("boxes")} ${problem.service}</span><span>${icon("map-pin")} ${problem.region}</span><span>${icon("crosshair")} ${operation.title}</span></div></div><div class="hero-actions"><div>${tag(outcome.status)}<small>outcome status</small></div></div></section><section class="outcome-detail-grid"><div class="surface outcome-comparison-card"><div class="surface-head"><div><p class="eyebrow">BEFORE / AFTER</p><h2>Evidence-backed improvement</h2></div></div><div class="outcome-comparison"><div><small>BEFORE OPERATION</small><strong>${outcome.beforeMetric.failureRate}%</strong><span>Failure rate · Availability ${outcome.beforeMetric.availability}%</span></div>${icon("arrow-right")}<div class="after"><small>AFTER OPERATION</small><strong>${outcome.afterMetric.failureRate}%</strong><span>Failure rate · Availability ${outcome.afterMetric.availability}%</span></div></div></div><aside class="surface outcome-detail-impact"><div class="surface-head"><div><p class="eyebrow">BUSINESS IMPACT</p><h2>What changed for China?</h2></div></div><div class="outcome-impact-grid"><div><small>USERS RECOVERED</small><strong>${outcome.impact.usersRecovered.toLocaleString()}</strong></div><div><small>DOWNTIME REDUCED</small><strong>${outcome.impact.downtimeReduced} min</strong></div><div><small>FAILURES REDUCED</small><strong>${outcome.impact.failureReduction}%</strong></div><div><small>CUSTOMER RISK</small><strong>${outcome.impact.customerRiskBefore} <i>${icon("arrow-right")}</i> ${outcome.impact.customerRiskAfter}</strong></div></div></aside></section><section class="surface outcome-evidence-detail"><div class="surface-head"><div><p class="eyebrow">OUTCOME EVIDENCE</p><h2>Independent proof</h2></div><a href="#/evidence">Evidence library ${icon("arrow-right")}</a></div>${evidence.map((item) => `<button class="evidence-row evidence-button" type="button" data-evidence-id="${item.id}"><span class="source-icon probe">${icon("radar")}</span><div><strong>${item.metric}</strong><p>${item.source} · ${item.timestamp}</p></div><div><b>${item.actual}</b><small>expected ${item.expected}</small></div>${tag(item.status)}</button>`).join("")}</section><section class="surface outcome-next-step"><div class="insight-icon">${icon("repeat-2")}</div><div><p class="eyebrow">LEARN</p><h2>Keep the improvement observable</h2><p>Continue monitoring the same Probe and availability evidence so recurrence becomes a new Signal instead of a hidden regression.</p></div><a class="primary-button" href="#/operations/${operation.id}">Open ${operation.id} ${icon("arrow-right")}</a></section>`;
}
function renderIncidents() { return `${pageHeader("SOURCE SYSTEM", "Incidents", "Backend-reported technical issues are one Signal Source, not the center of the Operation Platform.", "")}<section class="source-notice">${icon("info")} <span>Incident is one Signal Source. <strong>Problems can exist without a reported Incident.</strong></span></section><section class="surface"><div class="table-wrap"><table><thead><tr><th>Incident</th><th>Related Problem</th><th>Priority</th><th>Owner</th><th>Created</th><th>Status</th></tr></thead><tbody>${state().incidents.map((incident) => `<tr><td><strong>${incident.title}</strong><small class="under-text">${incident.id}</small></td><td>${problemLink(incident.problemId)}</td><td>${tag(incident.priority)}</td><td>${incident.owner}</td><td>${incident.created}</td><td>${tag(incident.status)}</td></tr>`).join("")}</tbody></table></div></section>`; }
function renderProbe() { return `${pageHeader("EVIDENCE GENERATOR", "Probe", "Probe remains an independent product. Operation consumes Probe Results as Evidence for verification.", `<button class="primary-button" type="button" data-action="run-probe" data-operation-id="OP-102">${icon("play")}Run Probe</button>`)}<section class="probe-grid">${state().probes.map((probe) => `<article class="probe-card"><div><span class="source-icon probe">${icon("radar")}</span>${tag(probe.status)}</div><h2>${probe.name}</h2><p>${probe.service} · ${probe.regions.join(", ")}</p><div class="probe-rate"><strong>${state().probeResults.filter((result) => result.probeId === probe.id).at(-1)?.actual || "—"}</strong><span>latest result</span></div><small>${state().probeResults.filter((result) => result.probeId === probe.id).length} Probe Results · independent source</small></article>`).join("")}</section><section class="surface probe-results-library"><div class="surface-head"><div><p class="eyebrow">RESULTS</p><h2>Probe Results become Evidence</h2></div></div>${state().probeResults.map((result) => `<div class="probe-result-row"><span class="source-icon probe">${icon("radar")}</span><div><strong>${result.id} · ${result.metric}</strong><p>${result.service} · ${result.region} · ${result.timestamp}</p></div><div><b>${result.actual}</b><small>Expected ${result.expected}</small></div>${tag(result.status)}</div>`).join("")}</section>`; }
function renderHistory() { const problem = find("problems", "PRB-204"); const operation = problem.operationIds.map((id) => find("operations", id)).find(Boolean); const events = state().historyEvents.filter((event) => event.problemId === problem.id); const outcome = state().outcomes.find((item) => item.problemId === problem.id); return `${pageHeader("LEARN", "Closed-loop History", "What happened and what did we learn? This record is driven by the same Prototype State as Problems, Operations, Evidence, and Outcome.", "")}<section class="history-hero"><div><p class="eyebrow">LIFECYCLE RECORD</p><h2>${problem.id} · ${problem.title}</h2><p>${problem.service} · ${problem.region} · ${tag(problem.status)}</p></div>${operation ? `<a class="secondary-button" href="#/operations/${operation.id}">${icon("crosshair")}Open ${operation.id}</a>` : ""}</section><section class="history-layout"><div class="surface history-timeline"><div class="surface-head"><div><p class="eyebrow">DETECT → UNDERSTAND → ACT → VERIFY → OUTCOME</p><h2>Evidence-backed history</h2></div></div><div class="timeline">${events.map(timelineItem).join("")}${events.length < 14 ? timelineItem({ timestamp: "Next state", type: "Continue the closed loop", description: "New events will appear here as the demo flow progresses.", status: "Next" }) : ""}</div></div><aside class="surface history-summary"><p class="eyebrow">CURRENT OUTCOME</p><h2>${outcome?.result || "Not yet achieved"}</h2><p>${outcome?.actual || "Complete verification to record an actual outcome."}</p><div class="history-counts"><div><small>EVENTS</small><strong>${events.length}</strong></div><div><small>EVIDENCE</small><strong>${state().evidences.filter((item) => item.problemId === problem.id).length}</strong></div><div><small>OUTCOMES</small><strong>${state().outcomes.filter((item) => item.problemId === problem.id).length}</strong></div></div></aside></section>`; }

function modal(title, content) { document.querySelector("#modal-content").innerHTML = `<p class="eyebrow">OPERATION PLATFORM V1</p><h2 id="modal-title">${title}</h2>${content}`; const backdrop = document.querySelector("#modal-backdrop"); backdrop.classList.add("is-open"); backdrop.setAttribute("aria-hidden", "false"); lucide.createIcons({ attrs: { "stroke-width": 1.8 } }); }
function closeModal() { const backdrop = document.querySelector("#modal-backdrop"); backdrop.classList.remove("is-open"); backdrop.setAttribute("aria-hidden", "true"); }
function showActionModal(operationId, failed = false) { modal(failed ? "Create New Action" : "Create Action", `<p class="modal-copy">Actions carry an owner, expected result, due date, and evidence trail. They do not complete the Operation automatically.</p><div class="form-preview"><label>Action name<input id="new-action-name" value="${failed ? "Investigate residual failure" : "Run regional Probe"}" /></label><label>Owner<input id="new-action-owner" value="Operation Engineer" /></label><label>Expected result<input id="new-action-result" value="${failed ? "Reduce remaining failure before verification" : "Capture current Approval Download failure rate"}" /></label></div><button class="primary-button full-button" type="button" data-action="save-action" data-operation-id="${operationId}">${icon("plus")}Create Action</button>`); }
function showProbeModal(operationId, actionId, verification = false) { modal(verification ? "Run Verification Probe" : "Run Probe", `<p class="modal-copy">Probe remains independent. This run creates a Probe Result and linked Evidence for the Operation.</p><div class="form-preview"><label>Service<input value="MIB3 Approval" readonly /></label><label>Region<input value="China" readonly /></label>${verification ? `<label>Mock verification result<select id="verification-result"><option value="pass">Passed · 0.6% · Availability 99.8%</option><option value="fail">Failed · 4.8% · Availability 97.4%</option></select></label>` : ""}</div><button class="primary-button full-button" type="button" data-action="confirm-probe" data-operation-id="${operationId}" data-action-id="${actionId || ""}" data-verification="${verification}">${icon("play")}Execute Probe</button>`); }

function renderRoute() {
  const cleanHash = location.hash.replace(/^#\//, "");
  const [path, queryString = ""] = cleanHash.split("?");
  const [route = "overview", id] = path.split("/");
  document.querySelectorAll("[data-route]").forEach((item) => item.classList.toggle("active", item.dataset.route === route));
  const query = Object.fromEntries(new URLSearchParams(queryString));
  const pages = {
    overview: () => { setBreadcrumb(["Operation Platform", "China Operation Overview"]); return renderOverview(); },
    "command-center": () => { setBreadcrumb(["Operation Platform", "Command Center"]); return renderCommandCenter(); },
    signals: () => { setBreadcrumb(["Operation Platform", "Signals", ...(id ? [id] : [])]); return id ? renderSignalDetail(id) : renderSignals(query); },
    problems: () => { setBreadcrumb(["Operation Platform", "Problems", ...(id ? [id] : [])]); return id ? renderProblemDetail(id) : renderProblems(query); },
    operations: () => { setBreadcrumb(["Operation Platform", "Operations", ...(id ? [id] : [])]); return id ? renderOperationDetail(id) : renderOperations(query); },
    evidence: () => { setBreadcrumb(["Operation Platform", "Evidence"]); return renderEvidence(); },
    outcomes: () => { setBreadcrumb(["Operation Platform", "Outcomes", ...(id ? [id] : [])]); return id ? renderOutcomeDetail(id) : renderHistory(); },
    incidents: () => { setBreadcrumb(["Operation Platform", "Incidents"]); return renderIncidents(); },
    probe: () => { setBreadcrumb(["Operation Platform", "Probe"]); return renderProbe(); },
    history: () => { setBreadcrumb(["Operation Platform", "History"]); return renderHistory(); }
  };
  app.innerHTML = (pages[route] || pages.overview)();
  document.querySelector("#nav-problem-count").textContent = state().problems.length;
  document.querySelector("#nav-incident-count").textContent = state().incidents.length;
  document.querySelector("#nav-operation-count").textContent = state().operations.length;
  document.querySelector("#nav-signal-count").textContent = state().signals.length;
  lucide.createIcons({ attrs: { "stroke-width": 1.8 } });
}

document.addEventListener("click", (event) => {
  const target = event.target.closest("[data-action]");
  if (target) {
    const action = target.dataset.action;
    const problemId = target.dataset.problemId;
    const operationId = target.dataset.operationId;
    const actionId = target.dataset.actionId;
    if (action === "reset") { stateApi.reset(); location.hash = "#/command-center"; return; }
    if (action === "investigate") { stateApi.startInvestigation(problemId); location.hash = `#/problems/${problemId}`; return; }
    if (action === "adopt-problem") { stateApi.createProblem({ id: problemId }); location.hash = `#/problems/${problemId}`; return; }
    if (action === "create-operation") { const operation = stateApi.createOperation(problemId); location.hash = `#/operations/${operation.id}`; return; }
    if (action === "create-problem-from-signal") { const signal = stateApi.getSignalById(target.dataset.signalId); const related = state().signals.filter((item) => item.service === signal.service && item.region === signal.region).map((item) => item.id); const problem = stateApi.createProblemFromSignals(related); location.hash = `#/problems/${problem.id}`; return; }
    if (action === "new-signal") { modal("Create Signal", `<p class="modal-copy">Create a mock Signal through the same contract used by future external integrations.</p><div class="form-preview"><label>Service<input id="new-signal-service" value="MIB3 Approval" /></label><label>Type<select id="new-signal-type"><option>Performance Degradation</option><option>Availability Degradation</option><option>Customer Impact</option></select></label><label>Metric value<input id="new-signal-value" type="number" value="8.4" /></label></div><button class="primary-button full-button" type="button" data-action="save-signal">${icon("radio-tower")}Create Signal</button>`); return; }
    if (action === "save-signal") { const signal = stateApi.createSignal({ service: document.querySelector("#new-signal-service").value, type: document.querySelector("#new-signal-type").value, value: Number(document.querySelector("#new-signal-value").value), threshold: 1, metric: { name: "failure_rate", value: Number(document.querySelector("#new-signal-value").value), threshold: 1, unit: "%" }, severity: "High", impact: { userAffected: 120, businessImpact: "Medium" } }); closeModal(); location.hash = `#/signals/${signal.id}`; return; }
    if (action === "create-action") { showActionModal(operationId, find("operations", operationId)?.verificationStatus === "Failed"); return; }
    if (action === "save-action") { stateApi.createAction(operationId, { name: document.querySelector("#new-action-name").value, owner: document.querySelector("#new-action-owner").value, expectedResult: document.querySelector("#new-action-result").value }); closeModal(); renderRoute(); return; }
    if (action === "run-probe") { showProbeModal(operationId, actionId, false); return; }
    if (action === "confirm-probe") { const verification = target.dataset.verification === "true"; const passed = document.querySelector("#verification-result")?.value !== "fail"; stateApi.runProbe({ operationId, actionId, verification, passed }); closeModal(); renderRoute(); return; }
    if (action === "complete-action") { stateApi.completeAction(actionId); renderRoute(); return; }
    if (action === "run-verification") { showProbeModal(operationId, null, true); return; }
    if (action === "record-verification") { stateApi.recordVerification(operationId); renderRoute(); return; }
    if (action === "correlation") { modal("Signal correlation", `<p class="modal-copy">Signals are grouped by service, region, issue family, and time window. Incident, Probe, and Availability remain independent sources.</p><div class="correlation-list"><span>${icon("radar")}Probe abnormality</span><span>${icon("activity")}Availability impact</span><strong>${icon("arrow-down")}PRB-204 Problem pattern</strong></div>`); return; }
  }
  const evidenceTarget = event.target.closest("[data-evidence-id]");
  if (evidenceTarget) { const item = find("evidences", evidenceTarget.dataset.evidenceId); if (item) modal(item.metric, `<dl class="evidence-detail"><dt>Evidence ID</dt><dd>${item.id}</dd><dt>Category</dt><dd>${item.category}</dd><dt>Source</dt><dd>${item.source} · ${item.sourceId || "-"}</dd><dt>Expected</dt><dd>${item.expected}</dd><dt>Actual</dt><dd>${item.actual}</dd><dt>Problem</dt><dd>${problemLink(item.problemId)}</dd><dt>Operation</dt><dd>${item.operationId ? operationLink(item.operationId) : "-"}</dd></dl>`); }
  if (event.target.closest("#modal-close") || event.target.closest("#modal-backdrop") === event.target || event.target.closest("[data-close-modal]")) closeModal();
  if (event.target.closest(".mobile-menu")) document.querySelector(".sidebar").classList.toggle("is-open");
});
window.addEventListener("hashchange", renderRoute);
window.addEventListener("prototype-state-change", renderRoute);
if (!location.hash) location.hash = "#/command-center";
renderRoute();
